/*
 * A023558  Convolution of A023531 and Lucas numbers.
 * https://oeis.org/A023558
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = Σ_{t∈T, 3≤t≤n+1} Lucas(n+2 – t) where T = {m(m+1)/2 |
 *            m≥2} (triangular numbers except 1) and Lucas is the Lucas
 *            sequence with Lucas(1)=1, Lucas(2)=3,
 *            Lucas(k)=Lucas(k-1)+Lucas(k-2) (k≥3) (A023558 is generated by
 *            convolving A023531 (indicator of T) with Lucas)
 * Range:     u8 n <= 12, u16 n <= 23, u32 n <= 33, u64 n <= 33, u128 n <= 33,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

static seq_t *lucas_cache = NULL;   /* 1‑based Lucas numbers (lucas_cache[1]=1, lucas_cache[2]=3) */
static idx_t lucas_max   = 0;        /* highest index currently cached */

/* Ensure lucas_cache contains Lucas numbers up to 'max_index' (inclusive).  */
static void ensure_lucas(idx_t max_index)
{
    if (lucas_cache == NULL) {
        /* Allocate enough space for indices 0…2 (index 0 unused). */
        size_t init_cap = 3;
        lucas_cache = (seq_t *)malloc(sizeof(seq_t) * init_cap);
        lucas_cache[0] = (seq_t)0;   /* unused placeholder */
        lucas_cache[1] = (seq_t)1;   /* Luc(1)  */
        lucas_cache[2] = (seq_t)3;   /* Luc(2)  */
        lucas_max = 2;
    }
    if (max_index > lucas_max) {
        size_t new_cap = (size_t)(max_index + 1);
        lucas_cache = (seq_t *)realloc(lucas_cache, sizeof(seq_t) * new_cap);
        for (idx_t i = lucas_max + 1; i <= max_index; ++i) {
            lucas_cache[i] = lucas_cache[i-1] + lucas_cache[i-2];
        }
        lucas_max = max_index;
    }
}

/* Convolution of A023531 and Lucas numbers. */
seq_t a(idx_t n)
{
    if (n < 1)           /* undefined for n<1; defined to be 0 for safety */
        return (seq_t)0;

    /* We need Lucas indices up to n-1 (largest when t=3). */
    idx_t lucas_needed = (n > 1 ? n-1 : 1);
    ensure_lucas(lucas_needed);

    seq_t sum = (seq_t)0;
    /* Loop over triangular numbers t = m(m+1)/2,  m ≥ 2,  t ≤ n+1. */
    for (idx_t m = 2;; ++m) {
        idx_t t = m * (m + 1) / 2;           /* t is a triangular number */
        if (t > n + 1)
            break;
        idx_t index = n + 2 - t;             /* Lucas index (>=1) */
        sum += lucas_cache[index];
    }
    return sum;
}
